import {storage,empty,configureStorage} from './data.js';
import {loadCatalog,recommend,reason,eligible} from './recommendations.js';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const genres=['commedia','thriller','crime','fantascienza','fantasy','animazione','documentari','drammatico','azione','horror','romantico','storico','family','anime','reality'];
const platforms=['Netflix','Prime Video','Disney+','NOW','Apple TV+','Paramount+','RaiPlay','Mediaset Infinity','Discovery+','YouTube'];
const moods=[['laugh','☺','Voglia di ridere'],['light','☁','Qualcosa di leggero'],['tension','ϟ','Un po’ di tensione'],['short','◷','Poco tempo'],['long','☾','Serata lunga'],['surprise','✦','Sorprendimi']];
let cloudMode=false,authRequired=false,syncIssue=false,interacting=false;
let state=empty(),catalog=[],view='home',step=1,selected=[],mood='',platform='',results=null,skip=[],editId=null,tasteId=null,error='',loadBlocked=false,deleteId=null;
const app=$('#app');
const toast=s=>{if(syncIssue)return;const t=$('#toast');t.textContent=s;t.style.display='block';setTimeout(()=>t.style.display='none',3500)};
async function save(){try{await storage.save(state);error='';return true}catch(e){error=e.message;if(cloudMode)syncIssue=true;return false}}
async function exclusive(fn){if(interacting)return;interacting=true;try{await fn()}catch(e){error=e.message;render()}finally{interacting=false}}
function loginPanel(){return head('Il vostro divano,<br><em>ovunque siate.</em>','Un accesso famiglia, gli stessi profili e le stesse serate su tutti i dispositivi. Non serve ChatGPT.','BENTORNATI A CASA')+`<section class="panel"><h2>Entra nell’archivio famiglia</h2><p class="sub">Usate tutti l’email e la password dedicate a questa app, create da chi la gestisce. I tre profili si scelgono dopo l’accesso.</p>${error?`<p class="error" role="alert">${esc(error)}</p>`:''}<form id="family-login" class="form-row" style="margin-top:25px"><label>Email dell’accesso famiglia<input type="email" name="email" required autocomplete="username"></label><label>Password dell’app<input type="password" name="password" required autocomplete="current-password"></label><button class="btn" type="submit">Entra in famiglia →</button></form><p class="notice">La password non viene salvata dall’app. Questo dispositivo conserva una sessione di accesso: usa «Esci» sui dispositivi condivisi con altre persone. Per reimpostare la password rivolgiti a chi gestisce il progetto Supabase.</p></section>`}
function syncPanel(){return head('Una modifica da<br><em>mettere d’accordo.</em>','La tua copia resta qui finché scegli come procedere. Nessuna modifica altrui è stata sovrascritta.','ARCHIVIO FAMIGLIA')+`<section class="panel"><h2>Salvataggio non completato</h2><p class="error" role="alert">${esc(error)}</p><p class="sub">Esporta la tua copia per conservare le modifiche. Poi riapri l’archivio famiglia e ripeti soltanto ciò che manca. Riaprendo, le modifiche locali non salvate verranno abbandonate.</p><div class="actions"><button class="btn" data-action="export">Esporta la mia copia</button><button class="btn ghost" data-action="reload-cloud">Riapri l’archivio famiglia</button></div></section>`}

function active(){return state.profiles.filter(p=>selected.includes(p.id))}
function avatar(p){return `<span class="avatar" style="--avatar:${p.color}">${esc(p.name.slice(0,1).toUpperCase())}</span>`}
function head(title,sub,eyebrow='IL TUO PICCOLO CINEMA DI CASA'){return `<div class="hero"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="sub">${sub}</p></div><div class="cinema" aria-hidden="true"><div class="screen"></div><div class="sofa">🛋</div></div></div>`}
function stepper(){return `<div class="stepper">${['La famiglia','Le piattaforme','I gusti','La serata'].map((s,i)=>`<span class="${step===i+1?'current':''}">${i+1}. ${s}</span>`).join('')}</div>`}
function profileForm(){const p=state.profiles.find(p=>p.id===editId);return `<form id="profile-form" class="muted-box"><h3>${p?'Modifica il profilo':'Una persona, un profilo'}</h3><p class="small">Basta un soprannome. L’età serve a scegliere titoli adatti.</p><div class="form-row"><label>Nome o soprannome<input name="name" required maxlength="40" autocomplete="off" value="${esc(p?.name??'')}" placeholder="Come ti chiami?"></label><label>Età in anni<input name="age" type="number" min="0" max="110" required value="${p?.age??''}" placeholder="Es. 12"></label><label>Il tuo colore<input name="color" type="color" value="${p?.color??'#dce7be'}"></label><button class="btn" type="submit">${p?'Salva modifiche':'Aggiungi profilo'}</button>${p?'<button type="button" class="text-btn" data-action="cancel-edit">Annulla</button>':''}</div></form>`}
function profilesPanel(onboarding=false){return `<section class="panel"><div class="section-head"><h2>${onboarding?'Chi c’è in famiglia?':'I vostri profili'}</h2><span class="pill">${state.profiles.length} persone</span></div><p class="sub">Ognuno ha i suoi gusti. Troviamo una storia che vi metta d’accordo.</p><div class="profile-list" style="margin-top:24px">${state.profiles.map(p=>`<div class="profile">${avatar(p)}<strong>${esc(p.name)}</strong><small>${p.age} anni</small><button class="text-btn" data-edit="${p.id}">Modifica</button><button class="text-btn" data-taste="${p.id}">I gusti</button><button class="text-btn" data-delete="${p.id}">Elimina</button></div>`).join('')}</div>${deleteId?`<div class="error">Eliminare questo profilo e le sue valutazioni?<div class="actions"><button class="btn danger" data-action="confirm-delete">Elimina profilo</button><button class="btn ghost" data-action="cancel-delete">Annulla</button></div></div>`:''}${profileForm()}${onboarding?`<div class="actions"><button class="btn" data-action="next-platforms" ${state.profiles.length?'':'disabled'}>Avanti: le piattaforme →</button><span class="small">Puoi aggiungerne quanti vuoi, anche più avanti.</span></div>`:''}</section>`}
function platformPanel(onboarding=false){const all=[...new Set([...platforms,...state.platforms])];return `<section class="panel"><h2>Dove guardate?</h2><p class="sub">Scegli solo le piattaforme che usate. Nessuna è selezionata in partenza.</p><div class="chips" style="margin-top:25px">${all.map((p,i)=>`<button class="chip ${state.platforms.includes(p)?'on':''}" aria-pressed="${state.platforms.includes(p)}" data-platform="${esc(p)}">${state.platforms.includes(p)?'✓ ':''}${esc(p)}</button>`).join('')}</div><form id="platform-form" class="form-row" style="margin-top:25px"><label>Ne manca una?<input name="platform" maxlength="50" required placeholder="Nome della piattaforma"></label><button class="btn ghost">Aggiungi</button></form><p class="notice">Il piccolo catalogo iniziale copre Netflix, Disney+ e Apple TV+. Le altre piattaforme restano salvate, pronte per ampliare il catalogo.</p>${onboarding?`<div class="actions"><button class="btn ghost" data-action="back-profiles">← Indietro</button><button class="btn" data-action="next-tastes" ${state.platforms.length?'':'disabled'}>Avanti: i gusti →</button></div>`:''}</section>`}
function tastePanel(onboarding=false){let p=state.profiles.find(p=>p.id===tasteId)??state.profiles[0];if(!p)return '<div class="empty">Crea prima un profilo.</div>';tasteId=p.id;
const famous=catalog.filter(t=>t.age<=p.age);let examples=[];for(const g of genres){const t=famous.find(t=>t.genres.includes(g)&&!examples.includes(t));if(t)examples.push(t)}examples=examples.slice(0,8);
return `<section class="panel"><div class="section-head"><div><h2>Cosa ti va di guardare?</h2><p class="sub">Bastano pochi tocchi. Puoi anche tornare dopo.</p></div>${avatar(p)}</div><div class="chips" style="margin-bottom:20px">${state.profiles.map(x=>`<button class="chip ${x.id===p.id?'on':''}" data-taste="${x.id}">${esc(x.name)}</button>`).join('')}</div>${genres.map(g=>`<div class="category-row"><strong>${g==='family'?'Per tutta la famiglia':g[0].toUpperCase()+g.slice(1)}</strong><div class="chips">${[[2,'♥ Mi piace molto'],[0,'◷ Ogni tanto'],[-2,'✕ Non lo sopporto']].map(([v,l])=>`<button class="chip ${p.tastes[g]===v?'on':''}" aria-pressed="${p.tastes[g]===v}" data-genre="${g}" data-value="${v}">${l}</button>`).join('')}</div></div>`).join('')}<h2 style="margin-top:30px">Questi li conosci?</h2><p class="small">Solo titoli con età consigliata fino a ${p.age} anni. Anche «Visto e mi è piaciuto» li esclude dai prossimi suggerimenti.</p>${examples.map(t=>`<div class="title-row"><strong>${esc(t.title)}</strong> <span class="small">${esc(t.genres.join(' · '))}</span><div class="chips">${[[1,'Visto e mi è piaciuto'],[-1,'Visto e non mi è piaciuto'],[2,'Non visto']].map(([v,l])=>`<button class="chip ${(v===2?p.ratings[t.id]===undefined:p.ratings[t.id]===v)?'on':''}" data-known="${t.id}" data-value="${v}">${l}</button>`).join('')}</div></div>`).join('')}${!examples.length?'<p class="notice">Non ci sono ancora esempi per questa età nel catalogo.</p>':''}<div class="actions">${onboarding?'<button class="btn ghost" data-action="back-platforms">← Indietro</button><button class="btn" data-action="finish">Andiamo alla serata →</button><button class="text-btn" data-action="finish">Salta per ora</button>':'<button class="btn" data-action="back-profiles-page">Fatto, torna ai profili</button>'}</div></section>`}
function pendingPanel(){if(!state.pending)return '';const t=catalog.find(t=>t.id===state.pending.titleId);return `<section class="panel"><span class="eyebrow">LA VOSTRA ULTIMA SCELTA</span><h2>Com’è andata con ${esc(t?.title??'questo titolo')}?</h2><p class="sub">Un tocco a testa ci aiuta a scegliere meglio la prossima volta.</p>${state.pending.participants.map(id=>{const p=state.profiles.find(p=>p.id===id);return p?`<div class="rating-row"><strong>${esc(p.name)}</strong><div class="chips">${[[1,'♥ Sì'],[0,'Così così'],[-1,'No']].map(([v,l])=>`<button class="chip ${state.pending.votes[id]===v?'on':''}" data-vote="${id}" data-value="${v}">${l}</button>`).join('')}</div></div>`:''}).join('')}<div class="actions"><button class="btn" data-action="finish-watch" ${state.pending.participants.every(id=>Object.hasOwn(state.pending.votes,id))?'':'disabled'}>Salva le opinioni</button><button class="text-btn" data-action="cancel-watch">Alla fine non l’abbiamo guardato</button></div></section>`}
function home(){return head('La serata è vostra.<br><em>La scelta la troviamo insieme.</em>','Meno tempo a cercare, più tempo sul divano. Scegli chi guarda e al resto pensiamo noi.')+pendingPanel()+`<section class="panel"><div class="section-head"><h2>Chi guarda stasera? <span class="step-label">01</span></h2><button class="text-btn" data-action="all">${selected.length===state.profiles.length?'Deseleziona tutti':'Ci siamo tutti'}</button></div><div class="profile-list">${state.profiles.map(p=>`<button class="profile ${selected.includes(p.id)?'selected':''}" aria-pressed="${selected.includes(p.id)}" data-person="${p.id}">${selected.includes(p.id)?'<span class="check">✓</span>':''}${avatar(p)}<strong>${esc(p.name)}</strong><small>${p.age} anni</small></button>`).join('')}<button class="add" data-nav="profiles">＋<br>Aggiungi profilo</button></div><h2 style="margin-top:30px">Che serata avete in mente? <span class="step-label">02</span></h2><div class="chips moods">${moods.map(([v,i,l])=>`<button class="chip ${mood===v?'on':''}" aria-pressed="${mood===v}" data-mood="${v}">${i} &nbsp;${l}</button>`).join('')}</div><div class="generate"><label>Una piattaforma in particolare?<select id="platform-filter"><option value="">Tutte le vostre piattaforme</option>${state.platforms.map(p=>`<option ${platform===p?'selected':''} value="${esc(p)}">${esc(p)}</option>`).join('')}</select></label><button class="btn" data-action="generate" ${selected.length&&!state.pending?'':'disabled'}>Trova la nostra serata &nbsp; ✦</button></div>${!selected.length?'<p class="notice">Scegli almeno una persona per cominciare.</p>':''}${state.pending?'<p class="notice">Completa il parere sull’ultima scelta, oppure annullala, per iniziare una nuova serata.</p>':''}</section>`+renderResults()}
function renderResults(){if(results===null)return `<div class="empty"><strong>Il prossimo «metti questo!» parte da qui.</strong>Seleziona le persone e l’umore: ti proponiamo tre strade diverse.</div>`;
return `<div class="result-head"><div><p class="eyebrow">IL VOSTRO PROSSIMO PLAY</p><h2>${results.length?'Tre modi per una bella serata':'Cerchiamo un’altra strada'}</h2><p>${esc(active().map(p=>p.name).join(' + '))} · ${moods.find(x=>x[0]===mood)?.[2]??'Qualunque umore'}</p></div><button class="text-btn" data-action="more">↻ Altre idee</button></div>${results.length<3?`<p class="notice">${results.length?`Restano ${results.length} idee compatibili.`:'Nessun titolo compatibile rimasto.'} Il catalogo è piccolo: prova un altro umore o una delle altre piattaforme attive. I filtri per età e titoli già visti restano sempre rispettati.</p>`:''}<div class="grid">${results.map((t,i)=>`<article class="card"><div class="art" style="--art:${t.color}"><span class="film-icon" aria-hidden="true">${i===2?'✦':'▸'}</span><strong>${esc(t.title)}</strong></div><div class="card-body"><div class="badge">${['01 · Andiamo sul sicuro','02 · Il punto d’incontro','03 · Fuori dal solito'][i]}</div><h3>${esc(t.title)}</h3><div class="meta">${t.type} · ${t.type==='Serie'?'≈ ':''}${t.minutes} min${t.type==='Serie'?' / episodio':''} · consigliato ${t.age}+<br>${esc(t.platforms.filter(p=>state.platforms.includes(p)&&(!platform||platform===p)).join(' · '))}</div><p class="description">${esc(t.description)}</p><p class="reason">${esc(reason(t,active()))}</p><button class="btn" data-choose="${t.id}">Va bene questo &nbsp; →</button><div class="card-actions"><button data-seen="${t.id}">✓ Già visto</button><button data-no="${t.id}">Non mi va</button></div><a class="small" href="${esc(t.source)}" target="_blank" rel="noopener">Scheda del titolo ↗</a></div></article>`).join('')}</div><p class="notice">ⓘ Controlla che il titolo sia ancora disponibile sulla piattaforma. Le durate delle serie sono indicative e variano con l’episodio. Le età sono consigli editoriali prudenti; verifica anche la scheda e i controlli parentali della piattaforma.</p>`}
function archive(){return (cloudMode?`<section class="panel"><div class="section-head"><div><h2>Il vostro archivio famiglia</h2><p class="sub">Le modifiche si aggiornano sugli altri dispositivi ogni dieci secondi, quando non state compilando un campo.</p></div><button class="btn ghost" data-action="logout">Esci da questo dispositivo</button></div></section>`:'')+head('Le vostre storie,<br><em>al sicuro qui.</em>',(cloudMode?'L’archivio è condiviso con i dispositivi che usano lo stesso accesso famiglia. Esportalo per conservarne una copia.':'L’archivio resta in questo browser. Esportalo per conservarne una copia o spostarlo su un altro dispositivo.'),'IL TUO ARCHIVIO')+`<div class="two-col"><section class="panel"><h2>Un piccolo backup, ogni tanto.</h2><p class="sub">Contiene profili, piattaforme, gusti e serate. ${cloudMode?'La copia online è riservata al vostro accesso famiglia.':'Nessun account in modalità locale.'}</p><div class="actions"><button class="btn" data-action="export">↓ Esporta archivio</button><label class="btn ghost" style="cursor:pointer">↑ Importa archivio<input id="import-file" type="file" accept="application/json,.json" hidden></label></div><p class="notice">L’importazione sostituisce l’archivio attuale${cloudMode?' per tutta la famiglia':''}, dopo una conferma. Prima puoi esportarne una copia.</p><div id="import-confirm"></div></section><section class="panel"><h2>La memoria delle serate</h2><p class="sub">${state.history.length} serate completate · ${state.profiles.length} profili</p>${state.history.slice().reverse().slice(0,15).map(h=>`<div class="history-row"><strong>${esc(catalog.find(t=>t.id===h.titleId)?.title??h.titleId)}</strong><p class="small">${new Date(h.date).toLocaleDateString('it-IT')} · ${esc(h.participants.map(id=>state.profiles.find(p=>p.id===id)?.name).filter(Boolean).join(', '))}</p></div>`).join('')||'<p class="small">La prima serata deve ancora cominciare.</p>'}<p class="notice">I «già visti» e i rifiuti si gestiscono nei gusti del profilo.</p></section></div>${platformPanel()}<section class="panel"><h2>I titoli segnati</h2><p class="sub">Hai toccato per sbaglio? Riabilita un titolo per un singolo profilo.</p>${state.profiles.map(p=>`<div class="title-row"><strong>${esc(p.name)}</strong>${Object.entries(p.ratings).map(([id,v])=>`<div class="history-row">${esc(catalog.find(t=>t.id===id)?.title??id)} <span class="small">· ${v===-1?'Non gradito':v===1?'Visto e piaciuto':'Già visto'}</span> <button class="text-btn" data-restore-person="${p.id}" data-restore-title="${esc(id)}">Riabilita</button></div>`).join('')||'<p class="small">Nessun titolo segnato.</p>'}</div>`).join('')}</section>`}
function render(){if(authRequired){app.innerHTML=loginPanel();return}if(syncIssue){app.innerHTML=syncPanel();return}document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===view));let html='';if(loadBlocked){app.innerHTML=`${head('L’archivio ha bisogno<br>di attenzione.','I dati esistenti non sono stati sovrascritti. Esporta una copia dal browser oppure importa un backup valido.')}<section class="panel"><p class="error">${esc(error)}</p><button class="btn" data-action="recover-export">Scarica i dati originali</button><label class="btn ghost">Importa un backup<input id="import-file" type="file" accept=".json" hidden></label><div id="import-confirm"></div></section>`;return}
if(!state.onboarded){html=head('Le belle serate<br><em>cominciano da voi.</em>','Prepariamo il vostro divano: pochi tocchi, nessuna lista da scrivere. Potrete cambiare tutto in ogni momento.','BENVENUTI A CASA')+stepper()+(step===1?profilesPanel(true):step===2?platformPanel(true):tastePanel(true));}else if(view==='profiles'){html=head('A ciascuno<br><em>la sua parte di storia.</em>','Aggiungi una persona, aggiorna l’età o affina i gusti. Ogni voce conta.','LE PERSONE SUL DIVANO')+(tasteId?tastePanel():profilesPanel());}else if(view==='settings')html=archive();else html=home();app.innerHTML=(error?`<p class="error" role="alert">${esc(error)}</p>`:'')+html;}
function resetResults(){results=null;skip=[]}
async function generate(more=false){if(!selected.length)return;if(more)skip.push(...(results??[]).map(t=>t.id));results=recommend(catalog,state,selected,mood,platform,skip);for(const t of results)state.exposures[t.id]=(state.exposures[t.id]??0)+1;await save();render();}
let imported=null;
document.addEventListener('click',e=>{const clicked=e.target.closest('button,a.brand');if(!clicked||(clicked.tagName==='BUTTON'&&clicked.type==='submit'&&clicked.closest('form')))return;if(interacting){e.preventDefault();return}return exclusive(async()=>{const b=e.target.closest('button,a.brand');if(!b)return;if(b.tagName==='BUTTON'&&b.type==='submit'&&b.closest('form'))return;const a=b.dataset.action;if(syncIssue&&!['export','reload-cloud'].includes(a))return;if(authRequired)return;
if(b.matches('a.brand')){e.preventDefault();view='home';render();return}
if(b.dataset.nav){if(!state.onboarded){toast('Completa i primi passi per aprire il menu.');return}view=b.dataset.nav;tasteId=null;editId=null;render();window.scrollTo(0,0);return}
if(b.dataset.person){const id=b.dataset.person;selected=selected.includes(id)?selected.filter(x=>x!==id):[...selected,id];resetResults()}
if(b.dataset.mood){mood=mood===b.dataset.mood?'':b.dataset.mood;resetResults()}
if(b.dataset.platform){const x=b.dataset.platform;state.platforms=state.platforms.includes(x)?state.platforms.filter(p=>p!==x):[...state.platforms,x];if(!state.platforms.includes(platform))platform='';resetResults();await save()}
if(b.dataset.edit){editId=b.dataset.edit;deleteId=null}
if(b.dataset.delete){deleteId=b.dataset.delete}
if(b.dataset.taste){tasteId=b.dataset.taste;editId=null;if(!state.onboarded)step=state.platforms.length?3:2}
if(b.dataset.genre){const p=state.profiles.find(p=>p.id===tasteId);const g=b.dataset.genre,v=Number(b.dataset.value);if(p.tastes[g]===v)delete p.tastes[g];else p.tastes[g]=v;resetResults();await save()}
if(b.dataset.known){const p=state.profiles.find(p=>p.id===tasteId);const id=b.dataset.known,v=Number(b.dataset.value);if(v===2)delete p.ratings[id];else p.ratings[id]=v;resetResults();await save()}
if(b.dataset.restorePerson){const p=state.profiles.find(p=>p.id===b.dataset.restorePerson);delete p.ratings[b.dataset.restoreTitle];resetResults();await save()}
if(b.dataset.choose){state.pending={titleId:b.dataset.choose,participants:[...selected],date:new Date().toISOString(),votes:{}};await save();results=null;toast('Buona visione! Raccontateci com’è andata, anche più tardi.');window.scrollTo(0,0)}
if(b.dataset.seen||b.dataset.no){const id=b.dataset.seen??b.dataset.no;for(const p of active())p.ratings[id]=b.dataset.no?-1:0;await save();await generate(false);toast(b.dataset.no?'Titolo escluso per chi guarda stasera.':'Segnato come visto per chi guarda stasera.');return}
if(b.dataset.vote){state.pending.votes[b.dataset.vote]=Number(b.dataset.value);await save()}
switch(a){case 'all':selected=selected.length===state.profiles.length?[]:state.profiles.map(p=>p.id);resetResults();break;
case 'cancel-edit':editId=null;break;case 'cancel-delete':deleteId=null;break;
case 'confirm-delete':state.profiles=state.profiles.filter(p=>p.id!==deleteId);selected=selected.filter(id=>id!==deleteId);for(const h of state.history){h.participants=h.participants.filter(id=>id!==deleteId);delete h.votes[deleteId]}if(state.pending){state.pending.participants=state.pending.participants.filter(id=>id!==deleteId);delete state.pending.votes[deleteId];if(!state.pending.participants.length)state.pending=null}if(editId===deleteId)editId=null;deleteId=null;if(!state.profiles.length){state.onboarded=false;step=1}resetResults();await save();break;
case 'next-platforms':step=2;break;case 'next-tastes':step=3;tasteId=state.profiles[0]?.id;break;case 'back-profiles':step=1;tasteId=null;break;case 'back-platforms':step=2;break;
case 'finish':state.onboarded=true;tasteId=null;view='home';selected=[];await save();break;case 'back-profiles-page':tasteId=null;break;
case 'generate':await generate(false);return;case 'more':await generate(true);return;
case 'finish-watch':{const h=state.pending;if(!h||!h.participants.every(id=>Object.hasOwn(h.votes,id)))return;for(const p of state.profiles.filter(p=>h.participants.includes(p.id)))p.ratings[h.titleId]=h.votes[p.id];state.history.push(h);state.pending=null;await save();toast('Opinioni salvate. La prossima scelta vi conoscerà un po’ meglio.');break;}
case 'cancel-watch':state.pending=null;await save();break;
case 'reload-cloud':try{const next=await storage.load();state=next;syncIssue=false;error='';selected=[];tasteId=null;editId=null;deleteId=null;resetResults()}catch(e){error=e.message;if(e.name==='AuthError'){authRequired=true;syncIssue=false}}break;
case 'logout':try{await storage.signOut()}catch{}state=empty();selected=[];syncIssue=false;authRequired=true;error='';resetResults();render();return;
case 'export':download(storage.export(state),'cosa-guardiamo-archivio.json');return;
case 'recover-export':download(localStorage.getItem('cosa-guardiamo-v1')??'','archivio-originale.json');return;
case 'confirm-import':if(imported){try{state=await storage.import(imported);loadBlocked=false;error='';selected=[];tasteId=null;step=1;imported=null;resetResults();toast('Archivio importato.')}catch(err){error=err.message}}break;
case 'cancel-import':imported=null;render();return;
}
render();if(['next-platforms','next-tastes','finish','back-platforms','back-profiles','back-profiles-page'].includes(a))window.scrollTo(0,0);
})});
document.addEventListener('submit',e=>{e.preventDefault();return exclusive(async()=>{const form=e.target;const f=new FormData(form);error='';if(form.id==='family-login'){await storage.signIn(String(f.get('email')).trim(),String(f.get('password')));try{state=await storage.load();authRequired=false;loadBlocked=false;selected=[];step=1;render()}catch(e){error='Accesso riuscito, ma archivio non disponibile. '+e.message;render()}return}if(form.id==='profile-form'){const name=String(f.get('name')).trim(),age=Number(f.get('age'));if(!name||!Number.isInteger(age)||age<0||age>110)return;const existing=state.profiles.find(p=>p.id===editId);if(existing)Object.assign(existing,{name,age,color:f.get('color')});else state.profiles.push({id:crypto.randomUUID(),name,age,color:f.get('color'),tastes:{},ratings:{}});editId=null;resetResults();await save();toast('Profilo salvato.')}if(form.id==='platform-form'){const s=String(f.get('platform')).trim();if(s&&!state.platforms.some(p=>p.toLowerCase()===s.toLowerCase()))state.platforms.push(s);await save()}render()})});
document.addEventListener('change',e=>exclusive(async()=>{if(e.target.id==='platform-filter'){platform=e.target.value;resetResults();render()}if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error('Il file è troppo grande (massimo 5 MB).');imported=await file.text();const {validate}=await import('./storage.js');const preview=validate(JSON.parse(imported));$('#import-confirm').innerHTML=`<div class="muted-box"><strong>Importare ${preview.profiles.length} profili e ${preview.history.length} serate?</strong><p>L’archivio attuale${cloudMode?' di tutta la famiglia':''} verrà sostituito.</p><div class="actions"><button class="btn" data-action="confirm-import">Sostituisci archivio</button><button class="btn ghost" data-action="cancel-import">Annulla</button></div></div>`;}catch(err){imported=null;error='Importazione non riuscita: '+err.message;render()}}}));
function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function updateFromCloud(){
 if(!cloudMode||authRequired||syncIssue||loadBlocked||interacting||document.hidden||document.activeElement?.matches('input,select,textarea'))return;
 await exclusive(async()=>{try{const changed=await storage.changed();const note=document.querySelector('.local-note');if(note)note.textContent='● Archivio famiglia condiviso';if(changed){state=await storage.load();selected=selected.filter(id=>state.profiles.some(p=>p.id===id));if(!state.profiles.some(p=>p.id===tasteId))tasteId=null;if(!state.profiles.some(p=>p.id===editId))editId=null;resetResults();error='';render();toast('Archivio aggiornato dalla famiglia.')}}catch(e){if(e.name==='AuthError'){authRequired=true;error=e.message;render()}else{const note=document.querySelector('.local-note');if(note)note.textContent='● Connessione da verificare'}}});
}
try{catalog=await loadCatalog();cloudMode=await configureStorage();const note=document.querySelector('.local-note');if(note)note.textContent=cloudMode?'● Archivio famiglia condiviso':'● Solo dispositivo · famiglia non collegata';
if(cloudMode&&!storage.authenticated){authRequired=true;render()}else{try{state=await storage.load()}catch(err){error=err.message;if(cloudMode){authRequired=true}else loadBlocked=true}render()}
if(cloudMode){setInterval(updateFromCloud,10000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateFromCloud()})}
}catch(err){app.innerHTML=`<section class="panel"><h1>Una piccola pausa.</h1><p>${esc(err.message)}</p><button class="btn" onclick="location.reload()">Riprova</button></section>`}
